To test this you can create a new ReactiveVar class like so:

```javascript
export const ReactiveVar = function (initialValue, equalsFunc) {
  if (! (this instanceof ReactiveVar))
  // called without `new`
    return new ReactiveVar(initialValue, equalsFunc);

  this.curValue = initialValue;
  this.equalsFunc = equalsFunc;
  this.dep = new _tracker.Dependency;
};

let _tracker = Tracker

ReactiveVar.setTracker = function (trackerReference) {
  _tracker = trackerReference
}

ReactiveVar._isEqual = function (oldValue, newValue) {
  let a = oldValue, b = newValue;
  // Two values are "equal" here if they are `===` and are
  // number, boolean, string, undefined, or null.
  if (a !== b)
    return false;
  else
    return ((!a) || (typeof a === 'number') || (typeof a === 'boolean') ||
      (typeof a === 'string'));
};

/**
 * @summary Returns the current value of the ReactiveVar, establishing a reactive dependency.
 * @locus Client
 */
ReactiveVar.prototype.get = function () {
  if (_tracker.active)
    this.dep.depend();

  return this.curValue;
};

/**
 * @summary Sets the current value of the ReactiveVar, invalidating the Computations that called `get` if `newValue` is different from the old value.
 * @locus Client
 * @param {Any} newValue
 */
ReactiveVar.prototype.set = function (newValue) {
  let oldValue = this.curValue;

  if ((this.equalsFunc || ReactiveVar._isEqual)(oldValue, newValue))
  // value is same as last time
    return;

  this.curValue = newValue;
  this.dep.changed();
};

ReactiveVar.prototype.toString = function () {
  return 'ReactiveVar{' + this.get() + '}';
};

ReactiveVar.prototype._numListeners = function() {
  // Tests want to know.
  // Accesses a private field of Tracker.Dependency.
  let count = 0;
  for (let id in this.dep._dependentsById)
    count++;
  return count;
};
```

Then import the Tracker and the ReactiveVar and see it working:

```javascript
import { ReactiveVar } from './reactive-var' // local js file
import { Tracker } from 'tracker' // installed npm module

ReactiveVar.setTracker(Tracker) // inject OUR Tracker

const counter = new ReactiveVar(0)

Tracker.autorun(() => {
   console.info(instance.counter.get())
})

setTimeout(() => instance.counter.set(instance.counter.get() + 1), 10)
setTimeout(() => instance.counter.set(instance.counter.get() + 1), 15)
setTimeout(() => instance.counter.set(instance.counter.get() + 1), 25)
```

